if (additionalEntries && additionalEntries.length > 0) {
                    for (let i = 0; i < additionalEntries.length; i++) {
                        const current = additionalEntries[i];
                        // They must only be added to the selectbox. The corresponding field description
                        // is already stored in m_profilingConfigurator
                        // Please note that we cannot check here, if e.g. the field is of type keyword for an aggregation or the
                        // like. We simply assume that the user knows what to configure
                        addHere.push( m_htmlInputModel.createOption(current.name, key, current.hideForOutput, current.disableForInput) );
                        //document.getElementById('hkTestList' ).appendChild( m_htmlInputModel.createOption(current.name, key, current.hideForOutput, current.disableForInput) );
                    }
                }
            });

            if ( predefinedMode ) {
                const listenerDescription = m_htmlInputModel.initResultButtonForPredefinedQueries(m_elasticsearchFilterManagerOptions.getResultButtonSelector, searchFunctionToCall);
                m_initializedEventListeners.push( listenerDescription );
            }
            else {
                // Now we add the options to the filter selectbox. If the number of fields is very large, we recommend the
                // usage of option groups to enhance human readability. These groups are configured via the used profiling
                // configurator. If an entry does not belong to a prepared option group it is stored in boxForOptionsWithoutGroup
                _addAllOptionsToFilterSelectbox( preparedOptionGroups, boxForOptionsWithoutGroup, vanillaNodeOrSelectorForSelectbox );

                const local_fieldChooserCallback = function (newElement) {
                    _handleNewlyChosenField( newElement, m_elasticsearchFilterManagerOptions.boxForNewlyCreatedInputElementsSelector );
                };

                // Add the callback to be executed, when the user chooses any selectbox entry from the filter chooser
                let listenerDescription = m_htmlInputModel.addFieldChooserSelectboxFunctionality(
                    vanillaNodeOrSelectorForSelectbox,
                    elasticsearchMappingModel,
                    m_elasticsearchFilterManagerOptions.boxForNewlyCreatedInputElementsSelector,
                    local_fieldChooserCallback
                );
                m_initializedEventListeners.push( listenerDescription );

                if ( HtmlModel.checkIfExists(m_elasticsearchFilterManagerOptions.getResultButtonSelector) ) {
                    // Bind a callback to the "getResults"-button
                    listenerDescription = m_htmlInputModel.initResultButton(
                        m_elasticsearchFilterManagerOptions.getResultButtonSelector,
                        m_elasticsearchFilterManagerOptions.boxForNewlyCreatedInputElementsSelector,
                        m_elasticsearchFilterManagerOptions.boxForOutputElementsSelector,
                        searchFunctionToCall
                    );
                    if ( listenerDescription !== null ) {
                        // a listener was installed. Store it
                        m_initializedEventListeners.push( listenerDescription );
                    }
                }


                if (m_elasticsearchFilterManagerOptions.offerPresetDateRange) {
                    // Here we add filters to be presented (and filled) automatically, when page is loaded
                    _handlePresetFilters();
                }
            }
            //m_htmlInputModel.initResultButton( m_elasticsearchFilterManagerOptions.getResultButtonSelector, m_profilingConfigurator.handleUserInputInToplevelSelector );

            console.info('Elasticsearch mapping was processed successfully');
        };
